 string clonePreviewPath;
 KokoroEngine EngineFor(VoiceProfile p){return new KokoroEngine{Root=root,Speaker=p.Speaker,Kind=p.Kind,ModelFolder=p.ModelFolder,VoiceName=p.Name,ReferencePath=p.ReferencePath,ReferenceText=p.ReferenceText,DeviceMode=SelectedDevice(),DeviceChanged=ShowDevice,ActivityChanged=ShowActivity,PreviewCache=measuredSpeech,Archive=proseInput||AnchoredMode||aiMode.SelectedIndex>0||mode.SelectedIndex==0?new SpeechArchive(stateDir):null,Threads=Math.Max(1,Math.Min(4,Environment.ProcessorCount))};}
 void SelectVoice(string key){var p=catalog.Get(key);if(!catalog.All.Any(v=>v.Key==key))return;styleFilter.SelectedIndex=0;family.SelectedIndex=(int)p.Kind;FillVoices();for(int i=0;i<voices.Items.Count;i++)if(((VoiceItem)voices.Items[i]).Key==key){voices.SelectedIndex=i;break;}}
 VoiceSettings CaptureSettings(){return new VoiceSettings{WorkflowMode=WorkflowChoice,AiMode=WorkflowChoice==2?2:0,AiFixShort=aiFixShort.Checked,TwoVoices=TwoSpeakers,VoiceBKey=SecondKey(),TextTargetChange=(double)textTargetChange.Value/100,AnchorSrt=anchoredSrt.Checked,Normalize=normalizeLoudness.Checked,TargetLufs=(double)targetLufs.Value,GentleFit=fitMode.SelectedIndex==0,MinSpeed=(double)minSpeed.Value,Punctuation=Math.Max(0,punctuationMode.SelectedIndex),CommaPause=(double)commaPause.Value,StopPause=(double)stopPause.Value,QuestionPause=(double)questionPause.Value,ParagraphPause=(double)paragraphPause.Value,Device=SelectedDevice(),Key=Key(),Mode=mode.SelectedIndex,Speed=(double)speed.Value,MaxSpeed=(double)maxSpeed.Value,Gap=(double)gap.Value,Slow=slow.Checked,Join=joinSentences.Checked,Breathing=breathMode.SelectedIndex,BreathEvery=(int)breathEvery.Value,BreathLevel=(double)breathVolume.Value,BreathPath=breathPath.Text,BatchMode=batchMode.SelectedIndex,Skip=skipFinished.Checked};}
 void Apply(VoiceSettings s){restoring=true;try{aiMode.SelectedIndex=s.AiMode;aiFixShort.Checked=s.AiFixShort;FillSecondVoice(s.VoiceBKey);voiceMode.SelectedIndex=s.TwoVoices?1:0;textTargetChange.Value=Clamp(s.TextTargetChange*100,textTargetChange);anchoredSrt.Checked=s.AnchorSrt;normalizeLoudness.Checked=s.Normalize;targetLufs.Value=Clamp(s.TargetLufs,targetLufs);fitMode.SelectedIndex=s.GentleFit?0:1;punctuationMode.SelectedIndex=Math.Max(0,Math.Min(1,s.Punctuation));commaPause.Value=Clamp(s.CommaPause,commaPause);stopPause.Value=Clamp(s.StopPause,stopPause);questionPause.Value=Clamp(s.QuestionPause,questionPause);paragraphPause.Value=Clamp(s.ParagraphPause,paragraphPause);devicePicker.SelectedIndex=s.Device=="gpu"?1:s.Device=="cpu"?2:0;SelectVoice(s.Key);mode.SelectedIndex=Math.Max(0,Math.Min(2,s.Mode));speed.Value=Clamp(s.Speed,speed);minSpeed.Maximum=speed.Value;minSpeed.Value=Clamp(Math.Min(s.MinSpeed,s.Speed),minSpeed);maxSpeed.Value=Clamp(Math.Max(s.MaxSpeed,s.Speed),maxSpeed);gap.Value=Clamp(s.Gap,gap);slow.Checked=s.Slow;joinSentences.Checked=s.Join;breathMode.SelectedIndex=Math.Max(0,Math.Min(2,s.Breathing));breathEvery.Value=Clamp(s.BreathEvery,breathEvery);breathVolume.Value=Clamp(s.BreathLevel,breathVolume);breathPath.Text=s.BreathPath;batchMode.SelectedIndex=Math.Max(0,Math.Min(3,s.BatchMode));skipFinished.Checked=s.Skip;}finally{restoring=false;}ApplyWorkflowChoice(s.WorkflowMode);if(proseInput)mode.SelectedIndex=1;RefreshQualityEnabled();RefreshProse();UpdateShared();}
 decimal Clamp(double v,NumericUpDown n){return Math.Max(n.Minimum,Math.Min(n.Maximum,(decimal)v));}
 void SaveSession(){if(restoring)return;try{SaveProseProject();SaveSourceAnchors();StateFiles.Write(Path.Combine(stateDir,"session.xml"),CaptureSettings().Xml());QueueStore.Save(Path.Combine(stateDir,"queue.xml"),jobs);}catch(Exception e){status.Text="Chưa lưu được phiên làm việc: "+e.Message;}}
 void SaveQueueIfChanged(){if(!stateLoaded)return;string signature=String.Join("|",jobs.Select(j=>j.InputPath+":"+j.State+":"+j.OutputPath+":"+j.ReportPath+":"+j.TargetSeconds.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+":"+j.Cues.Count));if(signature!=queueSignature){try{QueueStore.Save(Path.Combine(stateDir,"queue.xml"),jobs);queueSignature=signature;}catch(Exception e){status.Text="Chưa lưu được hàng đợi: "+e.Message;}}UpdateShared();}
 void UpdateShared(){if(batchInfo==null||voices.SelectedItem==null)return;batchInfo.Text=jobs.Count+" file • "+jobs.Count(j=>j.State==JobState.Done)+" xong • "+jobs.Count(j=>j.State==JobState.Failed||j.State==JobState.ImportFailed)+" lỗi\nDùng chung: "+(TwoSpeakers?"A: "+catalog.Get(Key()).Name+" / B: "+(SecondKey()==""?"chưa chọn":catalog.Get(SecondKey()).Name):catalog.Get(Key()).Name)+" • "+SelectedDeviceLabel()+" • tốc độ "+speed.Value.ToString("0.00")+" • hơi thở "+breathMode.SelectedItem+" • "+batchMode.SelectedItem+" • nghỉ dấu câu: "+(punctuationMode.SelectedIndex==1?"Tùy chỉnh":"Auto")+" • căn nhịp: "+(fitMode.SelectedIndex==0?"Nhẹ ±10%":"Theo giới hạn")+" • Chế độ: "+(WorkflowChoice==2?"2 · AI tự động / 2 báo cáo":"1 · giữ lời / 1 báo cáo")+" • TXT tối đa ±"+textTargetChange.Value.ToString("0")+"% • âm lượng: "+(normalizeLoudness.Checked?targetLufs.Value.ToString("0")+" LUFS":"Gốc");}
