 void FillPresets(){presetPicker.Items.Clear();presetPicker.Items.AddRange(presets.Cast<object>().ToArray());if(presets.Count>0)presetPicker.SelectedIndex=0;}
 void SavePreset(){using(var f=new Form{Text="Lưu bộ thiết lập",Size=new Size(450,160),StartPosition=FormStartPosition.CenterParent}){var t=new TextBox{Dock=DockStyle.Top,Text=presetPicker.SelectedItem==null?"Phong cách riêng":presetPicker.SelectedItem.ToString()};var b=new Button{Text="Lưu",Dock=DockStyle.Bottom,Height=38};f.Controls.Add(t);f.Controls.Add(b);b.Click+=(s,e)=>{try{string name=t.Text.Trim();if(name.Length<1||name.Length>80)throw new Exception("Tên cần 1–80 ký tự.");var p=CaptureSettings();p.Name=name;presets.RemoveAll(x=>x.Name.Equals(name,StringComparison.OrdinalIgnoreCase));presets.Add(p);StateFiles.Write(Path.Combine(stateDir,"presets.xml"),new XElement("presets",presets.Select(x=>x.Xml())));FillPresets();f.Close();}catch(Exception x){Error(x);}};f.ShowDialog(this);}}
