 void CompareVoices(){
  using(var f=new Form{Text="So sánh 3–5 giọng trên cùng lời đọc",Size=new Size(970,720),MinimumSize=new Size(800,600),StartPosition=FormStartPosition.CenterParent}){
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=5,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,85));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,150));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));f.Controls.Add(layout);
   var filters=new FlowLayoutPanel{Dock=DockStyle.Fill};var search=new TextBox{Width=200};var gender=new ComboBox{Width=100,DropDownStyle=ComboBoxStyle.DropDownList};gender.Items.AddRange(new object[]{"Tất cả","Nam","Nữ"});gender.SelectedIndex=0;var style=new ComboBox{Width=240,DropDownStyle=ComboBoxStyle.DropDownList};style.Items.AddRange(VoiceStyles.Names);style.SelectedIndex=0;var fav=new CheckBox{Text="Yêu thích",AutoSize=true};filters.Controls.AddRange(new Control[]{search,gender,style,fav});layout.Controls.Add(filters,0,0);
   var text=new TextBox{Multiline=true,Dock=DockStyle.Fill,Text=cues.Count>0?String.Join(" ",cues.Take(3).Select(c=>c.Text)):"You thought it was a coincidence. But your brain had already noticed the pattern."};layout.Controls.Add(text,0,1);
   var list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,DisplayMember="Name"};layout.Controls.Add(list,0,2);var chosen=new HashSet<string>();bool filling=false;
   list.ItemCheck+=(s,e)=>{if(filling)return;var p=(VoiceProfile)list.Items[e.Index];if(e.NewValue==CheckState.Checked){if(chosen.Count>=5){e.NewValue=CheckState.Unchecked;return;}chosen.Add(p.Key);}else chosen.Remove(p.Key);};
   Action fill=()=>{filling=true;list.Items.Clear();foreach(var p in catalog.All.Where(p=>(gender.SelectedIndex==0||p.Gender.StartsWith(gender.Text))&&p.MatchesStyle(style.SelectedIndex==0?"":style.Text)&&(!fav.Checked||favorites.Contains(p.Key))&&(p.Name+" "+p.Description+" "+p.Styles).ToLowerInvariant().Contains(search.Text.ToLowerInvariant())))list.Items.Add(p,chosen.Contains(p.Key));filling=false;};search.TextChanged+=(s,e)=>fill();gender.SelectedIndexChanged+=(s,e)=>fill();style.SelectedIndexChanged+=(s,e)=>fill();fav.CheckedChanged+=(s,e)=>fill();fill();
   var results=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};layout.Controls.Add(results,0,3);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(actions,0,4);var note=new Label{Text="Chọn 3–5 giọng • cùng văn bản và tốc độ • không chèn hơi thở ngoài",AutoSize=true};string folder=Path.Combine(Path.GetTempPath(),"V15_compare_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);bool working=false;
