  o.Breathing=BreathMode.None;string none=await Task.Run(()=>Renderer.Render(sample,engine,o,Path.Combine(folder,"khong_hoi_tho.wav"),(p,m)=>{}));o.Breathing=selected;string with=await Task.Run(()=>Renderer.Render(sample,engine,o,Path.Combine(folder,"co_hoi_tho.wav"),(p,m)=>{}));SetBusy(false);
