 }catch(OperationCanceledException){status.Text="Đã dừng nghe thử hơi thở.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);if(player!=null)player.Stop();try{Directory.Delete(folder,true);}catch{}}}
